const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export function reviseArticle(article) {
  const edit = editorialRevisions[article?.slug];
  if (!edit) return article;
  let content = String(article.content || '');
  const marker = content.match(/<!-- taxsimba-(?:priority20-depth|guide-depth) -->/);
  if (edit.body && marker) content = '<p>' + escapeHtml(edit.answer) + '</p>\n' + edit.body + '\n' + content.slice(marker.index);
  else content = content.replace(/^\s*<p>[\s\S]*?<\/p>/i, '<p>' + escapeHtml(edit.answer) + '</p>');
  if (edit.extra && !content.includes('<!-- taxsimba-editorial-extra -->')) {
    const at = content.match(/<!-- taxsimba-(?:priority20-depth|guide-depth) -->/);
    const extra = '<!-- taxsimba-editorial-extra -->\n' + edit.extra + '\n';
    content = at ? content.slice(0,at.index) + extra + content.slice(at.index) : content + extra;
  }
  if (edit.replacementExample) content = content.replace(/<section class="article-worked-example"[^>]*>[\s\S]*?<\/section>/, edit.replacementExample);
  // Utility components can be shared. Do not make readers repeat the same advice
  // in a checklist, a table, two FAQ intros and a second price-comparison widget.
  content = content
    .replace(/<h2>A decision guide for this situation<\/h2>\s*/g, '')
    .replace(/<caption>What to check and how to act<\/caption>/g, '<caption>Actions to take</caption>')
    .replace(/<h2>Two more questions you may have<\/h2>\s*/g, '')
    .replace(/(<section class="article-follow-up"[^>]*>)([\s\S]*?)(<\/section>)/g, (_,open,body,close) => open + body.replace(/<h3>/g,'<h2>').replace(/<\/h3>/g,'</h2>') + close)
    .replace(/<p class="premium-kicker">Put it into practice<\/p>\s*/g, '')
    .replace(/<p class="article-example-label">Illustrative scenario — not a customer case or personal tax calculation\.<\/p>/g, '<p class="article-example-label">Illustrative example.</p>')
    .replace(/<h2>Your preparation worksheet<\/h2>/g, '<h2>Download a checklist for this guide</h2>')
    .replace(/<p>Use these prompts to prepare for a conversation with your accountant\. No signup is needed to download the plain-text checklist\.<\/p>\s*/g, '')
    .replace(/<p class="article-example-label">Save completed notes securely\. Keep passwords and security codes out of your notes\.<\/p>\s*/g, '')
    .replace(/<p>General information only — not personal tax advice\.<\/p>\s*/g, '');
  const words = content.replace(/<[^>]*>/g,' ').split(/\s+/).filter(Boolean).length;
  const sources = [...(article.sources || [])];
  for (const source of edit.sources || []) if (!sources.some(s => s.url===source.url)) sources.push(source);
  return { ...article, content, answer: edit.answer,
    ...(edit.title ? {title:edit.title} : {}),
    ...(edit.metaTitle ? {metaTitle:edit.metaTitle} : {}),
    ...(edit.metaDescription ? {metaDescription:edit.metaDescription} : {}),
    ...(edit.deadlineSwitch ? {deadlineSwitch:edit.deadlineSwitch} : {}),
    sources, wordCount:words, readingMinutes:Math.max(1,Math.ceil(words/200)),
    contentUpdatedAt:EDITORIAL_REVISION_AT, editorialRevisionVersion:2,
    competitiveRevisionVersion:edit.competitiveRevisionVersion || null,
    // An organisation name is a publisher attribution, not a named expert reviewer.
    reviewerName:'', reviewedAt:null, independentReviewStatus:'not-performed',
    editorialQualityStatus:'revised-pending-qualified-review',
    editorialReviewStatus:'ai-assisted-editorial-revision',
    releaseReadiness:'publisher-review-required',
    editorialReviewBasis:'AI-assisted editorial revision; selected current official-source checks; no independent sign-off',
  };
}
